// Uso bajo demanda: ?web=dominio.com  (opcional: &max=50 &formato=html &sitemap=URL)
const q = $input.first().json.query || {};
let web = String(q.web || q.sitemap || '').trim();
if (!web) throw new Error('Falta la web: añade ?web=dominio.com a la URL');
if (!/^https?:\/\//i.test(web)) web = 'https://' + web;
return [{ json: {
  modo: 'bajo demanda',
  web: web.match(/^https?:\/\/[^\/]+/i)[0],
  sitemap: /\.xml(\?|$)/i.test(web) ? web : (q.sitemap || ''),
  max: Math.min(Math.max(Number(q.max) || 50, 1), 300),
  formato: String(q.formato || 'json').toLowerCase()
} }];

// Webs que se vigilan cada lunes. Una línea por cliente: web, máximo de páginas y canal de Slack donde avisar.
const CLIENTES = [
  { web: 'https://www.ejemplo.com', max: 60, canal: 'TU_CANAL_CLIENTE' },
  // { web: 'https://otrocliente.com', max: 100, canal: 'ID_DEL_CANAL' },
];
return CLIENTES.map(c => ({ json: { modo: 'vigilancia', formato: 'json', sitemap: '', ...c } }));

// Auditar web: recibe una o varias webs y devuelve un informe por cada una.
// Todo va en un nodo para que el flujo sea corto: rastreo, análisis, priorización y comparación con la semana anterior.

const CONCURRENCIA = 4;          // páginas que se descargan a la vez
const TIMEOUT_MS = 15000;        // tiempo máximo por petición
const PRESUPUESTO_MS = 150000;   // tiempo máximo por web (protege frente a webs enormes)
const UA = 'Mozilla/5.0 (compatible; AuditorSEO-n8n/1.0)';

// ---------- Catálogo de problemas: gravedad, por qué importa y cómo se arregla ----------
const CATALOGO = {
  web_inaccesible:      ['critico', 'La web no responde', 'Si no carga para la auditoría, tampoco carga para Google ni para los clientes.', 'Revisar hosting, DNS y certificado SSL.'],
  robots_bloquea_todo:  ['critico', 'El robots.txt bloquea todo el sitio', 'Google no puede rastrear ninguna página: la web irá desapareciendo de los resultados.', 'Quitar "Disallow: /" del bloque "User-agent: *".'],
  noindex:              ['critico', 'Páginas del sitemap marcadas con noindex', 'Se pide a Google que las indexe (sitemap) y a la vez que no (noindex). Si es la home, la web deja de aparecer.', 'Quitar el noindex o sacar esas URLs del sitemap.'],
  error_http:           ['critico', 'URLs del sitemap con error 4xx/5xx', 'El usuario ve un error y Google gasta rastreo en páginas rotas.', 'Arreglar la página o quitarla del sitemap y redirigirla con un 301.'],
  sin_respuesta:        ['importante', 'URLs que no responden a tiempo', 'Una página que tarda más de 15 s o se cae no se rastrea ni se indexa bien.', 'Revisar servidor, caché y plugins pesados.'],
  respuesta_incompleta: ['importante', 'HTML incompleto', 'Si la página llega cortada, Google puede no ver el contenido ni las etiquetas.', 'Buscar errores del servidor o del tema que cortan la página.'],
  sitemap_no_encontrado:['importante', 'No hay sitemap accesible', 'Google descubre peor las páginas nuevas o profundas. Solo se ha podido revisar la home.', 'Generar sitemap.xml y declararlo en robots.txt y en Search Console.'],
  redirige:             ['importante', 'URLs del sitemap que redirigen', 'El sitemap debe listar solo URLs finales: cada redirección gasta rastreo.', 'Poner en el sitemap la URL de destino.'],
  canonical_otra:       ['importante', 'Canonical apuntando a otra URL', 'Se le dice a Google que la página buena es otra, así que esta no posicionará.', 'Canonical a sí misma, salvo duplicados intencionados.'],
  nap_distinto:         ['importante', 'Teléfono o dirección del schema distintos a la home', 'Datos de contacto contradictorios restan confianza en búsquedas locales y en Google Maps.', 'Un único bloque de negocio con los datos reales en toda la web.'],
  sin_title:            ['importante', 'Páginas sin title', 'Es lo primero que se ve en Google y una de las señales de relevancia más fuertes.', 'Title único de 30–60 caracteres con la búsqueda principal.'],
  title_duplicado:      ['importante', 'Titles duplicados', 'Google no sabe qué página mostrar para cada búsqueda y se pisan entre ellas.', 'Un title distinto en cada página.'],
  sin_h1:               ['importante', 'Páginas sin H1', 'El H1 le dice a Google y al usuario de qué trata la página.', 'Un H1 visible con el tema principal de la página.'],
  sin_meta:             ['recomendacion', 'Páginas sin meta description', 'Google se inventa el texto del resultado y suele atraer menos clics.', 'Meta de 140–155 caracteres que invite a entrar.'],
  meta_duplicada:       ['recomendacion', 'Meta descriptions duplicadas', 'Resultados iguales en Google para páginas distintas: menos clics.', 'Una meta distinta en cada página.'],
  meta_longitud:        ['recomendacion', 'Meta description demasiado corta o larga', 'Por debajo de 70 caracteres se queda pobre; por encima de 160, Google la corta.', 'Ajustar a 140–155 caracteres.'],
  title_longitud:       ['recomendacion', 'Title demasiado corto o largo', 'Corto desaprovecha espacio; largo, Google lo corta y puede reescribirlo.', 'Ajustar a 30–60 caracteres.'],
  varios_h1:            ['recomendacion', 'Varios H1 en la misma página', 'Diluye el tema principal de la página.', 'Dejar un H1 y pasar el resto a H2.'],
  sin_alt:              ['recomendacion', 'Imágenes sin texto alternativo', 'Accesibilidad y posicionamiento en Google Imágenes.', 'Alt descriptivo; alt vacío solo en imágenes decorativas.'],
  bots_ia:              ['recomendacion', 'Bloquea a los buscadores de IA', 'ChatGPT, Perplexity o Claude no podrán leer ni citar la web.', 'Permitir sus bots de búsqueda si interesa aparecer en respuestas de IA.'],
  sin_llms:             ['recomendacion', 'No hay llms.txt', 'Ayuda a los asistentes de IA a entender el negocio y sus páginas clave.', 'Publicar /llms.txt con descripción, contacto y enlaces principales.'],
  sitemap_fuera_robots: ['recomendacion', 'El robots.txt no declara el sitemap', 'Es la forma estándar de que cualquier buscador lo encuentre.', 'Añadir la línea "Sitemap: https://…/sitemap.xml".']
};
const ORDEN = { critico: 0, importante: 1, recomendacion: 2 };
const PESO = { critico: 30, importante: 12, recomendacion: 4 };

// ---------- Utilidades ----------
const pedir = async (url, seguirRedirecciones = true) => {
  for (let intento = 1; intento <= 2; intento++) {
    try {
      const r = await this.helpers.httpRequest({
        url, method: 'GET', returnFullResponse: true, json: false, encoding: 'utf8',
        ignoreHttpStatusErrors: true, timeout: TIMEOUT_MS, disableFollowRedirect: !seguirRedirecciones,
        headers: { 'User-Agent': UA }
      });
      const body = typeof r.body === 'string' ? r.body : (r.body ? String(r.body) : '');
      return { status: r.statusCode, body, headers: r.headers || {} };
    } catch (e) {
      if (intento === 2) return { status: 0, body: '', headers: {}, error: String(e.message || e).slice(0, 120) };
    }
  }
};
const enParalelo = async (lista, n, fn) => {
  const salida = new Array(lista.length); let i = 0;
  await Promise.all(Array.from({ length: Math.min(n, lista.length) }, async () => {
    while (i < lista.length) { const k = i++; salida[k] = await fn(lista[k], k); }
  }));
  return salida;
};
const limpiar = s => (s || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&ndash;/g, '–').replace(/&#39;|&#039;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const meta = (html, nombre) => ((html.match(new RegExp(`<meta[^>]+name=["']${nombre}["'][^>]*content=["']([^"']*)["']`, 'i'))
  || html.match(new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*name=["']${nombre}["']`, 'i')) || [])[1] || '').trim();
const sinBarra = u => (u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
const normDir = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
const locs = (xml, etiqueta) => [...xml.matchAll(new RegExp(`<${etiqueta}>\\s*<loc>([^<]+)</loc>`, 'g'))].map(m => m[1].trim().replace(/&amp;/g, '&'));
const esHtml = u => !/\.(md|txt|xml|json|pdf|jpe?g|png|webp|gif|svg|zip)(\?|$)/i.test(u);

function analizarHtml(url, html) {
  const title = limpiar((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const desc = meta(html, 'description');
  const robots = meta(html, 'robots').toLowerCase();
  const canonical = (html.match(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']*)["']/i) || html.match(/<link[^>]+href=["']([^"']*)["'][^>]*rel=["']canonical["']/i) || [])[1] || '';
  const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => limpiar(m[1]));
  const imgs = [...html.matchAll(/<img\b[^>]*>/gi)].map(m => m[0]);
  const sinAlt = imgs.filter(t => !/\balt=["'][^"']+["']/i.test(t)).length;
  const nodos = [...html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)]
    .map(m => { try { return JSON.parse(m[1]); } catch (e) { return null; } }).filter(Boolean)
    .flatMap(b => [].concat(b['@graph'] || b));
  const tels = [...new Set(nodos.map(n => String(n.telephone || n.telePhone || '').replace(/\D/g, '')).filter(Boolean))];
  const dirs = [...new Set(nodos.map(n => n.address && n.address.streetAddress).filter(Boolean))];
  return { title, desc, robots, canonical, h1s, imgs: imgs.length, sinAlt, tels, dirs, incompleta: html.length > 500 && !/<\/html>/i.test(html.slice(-3000)) };
}

// ---------- Auditoría de una web ----------
async function auditar(cfg) {
  const inicio = Date.now();
  const notas = [];
  const problemasPorId = {};
  const anota = (id, url, detalle) => {
    const p = problemasPorId[id] || (problemasPorId[id] = { id, paginas: [], detalles: [] });
    if (url && !p.paginas.includes(url)) { p.paginas.push(url); if (detalle) p.detalles.push(detalle); }
  };

  let origen = cfg.web.match(/^https?:\/\/[^\/]+/i)[0];
  const home = await pedir(origen + '/');
  if (!home.status || home.status >= 500) {
    anota('web_inaccesible');
    return { origen, inicio, paginas: [], problemasPorId, notas: [`La home respondió ${home.status ? 'HTTP ' + home.status : 'con error: ' + (home.error || 'sin respuesta')}`], sitio: {}, total: 0 };
  }

  // robots.txt y llms.txt
  const robots = await pedir(origen + '/robots.txt');
  const botsIA = ['GPTBot', 'OAI-SearchBot', 'ChatGPT-User', 'ClaudeBot', 'Claude-SearchBot', 'PerplexityBot', 'Google-Extended'];
  const bloqueados = new Set(); let bloqueaTodo = false, agentes = [], enReglas = false;
  if (robots.status === 200) {
    for (const linea of robots.body.split(/\r?\n/)) {
      const l = linea.replace(/#.*/, '').trim(); if (!l.includes(':')) continue;
      const clave = l.slice(0, l.indexOf(':')).trim().toLowerCase(), valor = l.slice(l.indexOf(':') + 1).trim();
      if (clave === 'user-agent') { if (enReglas) { agentes = []; enReglas = false; } agentes.push(valor.toLowerCase()); continue; }
      enReglas = true;
      if (clave === 'disallow' && valor === '/') { if (agentes.includes('*')) bloqueaTodo = true; botsIA.forEach(b => { if (agentes.includes(b.toLowerCase())) bloqueados.add(b); }); }
    }
  }
  const llms = await pedir(origen + '/llms.txt');
  const sitio = {
    robotsTxt: robots.status === 200,
    sitemapEnRobots: /^\s*sitemap:/mi.test(robots.body),
    robotsBloqueaTodo: bloqueaTodo,
    botsIABloqueados: [...bloqueados],
    llmsTxt: llms.status === 200 && !/<html/i.test(llms.body.slice(0, 500))
  };
  if (bloqueaTodo) anota('robots_bloquea_todo');
  if (bloqueados.size) anota('bots_ia');
  if (!sitio.llmsTxt) anota('sin_llms');
  if (sitio.robotsTxt && !sitio.sitemapEnRobots) anota('sitemap_fuera_robots');

  // Sitemap: el indicado, el de robots.txt o las rutas típicas. Si es un índice, entra en cada sitemap hijo.
  const esSitemap = r => r.status === 200 && /<(urlset|sitemapindex)[\s>]/i.test(r.body);
  let sitemapUrl = cfg.sitemap || '', raiz = null;
  const candidatos = [sitemapUrl, ...[...robots.body.matchAll(/^\s*sitemap:\s*(\S+)/gim)].map(m => m[1]), origen + '/sitemap.xml', origen + '/sitemap_index.xml', origen + '/wp-sitemap.xml'].filter(Boolean);
  for (const c of [...new Set(candidatos)]) { const r = await pedir(c); if (esSitemap(r)) { sitemapUrl = c; raiz = r; break; } }
  const grupos = [];
  if (raiz) {
    origen = sitemapUrl.match(/^https?:\/\/[^\/]+/i)[0];
    const hijos = locs(raiz.body, 'sitemap').filter(u => !/^https?:\/\/[^\/]+\/(en|fr|de|pt|it|ca)\//i.test(u));
    if (hijos.length) {
      for (const h of hijos.slice(0, 30)) {
        const r = await pedir(h);
        if (esSitemap(r)) grupos.push({ sitemap: h.replace(origen, ''), urls: locs(r.body, 'url').filter(esHtml) });
        else notas.push(`Sitemap hijo no válido: ${h}`);
      }
    } else grupos.push({ sitemap: sitemapUrl.replace(origen, ''), urls: locs(raiz.body, 'url').filter(esHtml) });
  } else {
    anota('sitemap_no_encontrado');
    if (cfg.sitemap) notas.push(`El sitemap indicado no es válido: ${cfg.sitemap}`);
  }
  const total = grupos.reduce((a, g) => a + g.urls.length, 0);

  // Muestra equilibrada (una URL de cada sitemap por turnos), empezando por la home
  const homeUrl = (grupos.flatMap(g => g.urls).find(u => sinBarra(u) === sinBarra(origen)) || origen + '/');
  const seleccion = new Set([homeUrl]);
  for (let i = 0; seleccion.size < cfg.max && grupos.some(g => g.urls.length > i); i++)
    for (const g of grupos) if (g.urls[i] && seleccion.size < cfg.max) seleccion.add(g.urls[i]);
  if (total > seleccion.size) notas.push(`Muestra de ${seleccion.size} de ${total} URLs del sitemap (límite: ${cfg.max}).`);

  // Descarga y análisis en paralelo, con tiempo máximo
  const paginas = await enParalelo([...seleccion], CONCURRENCIA, async (url) => {
    if (Date.now() - inicio > PRESUPUESTO_MS) return { url, omitida: true };
    const r = await pedir(url, false);
    const p = { url, status: r.status };
    if (r.status >= 300 && r.status < 400) { p.destino = r.headers.location || ''; return p; }
    if (!r.status) { p.error = r.error; return p; }
    if (r.status >= 400) return p;
    return { ...p, ...analizarHtml(url, r.body) };
  });
  const omitidas = paginas.filter(p => p.omitida).length;
  if (omitidas) notas.push(`Auditoría parcial: ${omitidas} URLs sin revisar por límite de tiempo (${PRESUPUESTO_MS / 1000} s).`);
  const revisadas = paginas.filter(p => !p.omitida);

  // Reglas por página
  const homeP = revisadas.find(p => p.url === homeUrl) || {};
  const refTel = (homeP.tels || [])[0], refDir = normDir((homeP.dirs || [])[0]);
  for (const p of revisadas) {
    if (!p.status) { anota('sin_respuesta', p.url, p.error); continue; }
    if (p.status >= 400) { anota('error_http', p.url, `HTTP ${p.status}`); continue; }
    if (p.status >= 300) { anota('redirige', p.url, `→ ${p.destino}`); continue; }
    if (p.incompleta) anota('respuesta_incompleta', p.url);
    if (p.robots.includes('noindex')) anota('noindex', p.url, p.url === homeUrl ? 'ES LA HOME' : '');
    if (!p.title) anota('sin_title', p.url); else if (p.title.length > 65 || p.title.length < 30) anota('title_longitud', p.url, `${p.title.length} caracteres`);
    if (!p.desc) anota('sin_meta', p.url); else if (p.desc.length < 70 || p.desc.length > 160) anota('meta_longitud', p.url, `${p.desc.length} caracteres`);
    if (!p.h1s.length) anota('sin_h1', p.url); else if (p.h1s.length > 1) anota('varios_h1', p.url, `${p.h1s.length} H1`);
    if (p.canonical && sinBarra(p.canonical) !== sinBarra(p.url)) anota('canonical_otra', p.url, `→ ${p.canonical}`);
    if (p.sinAlt) anota('sin_alt', p.url, `${p.sinAlt}/${p.imgs}`);
    const telMal = refTel && p.tels.some(t => t.slice(-9) !== refTel.slice(-9));
    const dirMal = refDir && p.dirs.some(d => normDir(d) !== refDir);
    if (telMal || dirMal) anota('nap_distinto', p.url, [...p.tels, ...p.dirs].join(' · '));
  }
  // Duplicados
  const dup = (campo, id) => {
    const m = {}; revisadas.forEach(p => { if (p[campo]) (m[p[campo]] = m[p[campo]] || []).push(p.url); });
    Object.entries(m).filter(([, u]) => u.length > 1).forEach(([v, us]) => us.forEach(u => anota(id, u, `"${v.slice(0, 60)}"`)));
  };
  dup('title', 'title_duplicado'); dup('desc', 'meta_duplicada');

  return { origen, inicio, paginas: revisadas, problemasPorId, notas, sitio, total, sitemapUrl, grupos, homeUrl };
}

// ---------- Ejecutar para cada web y montar el resultado ----------
const salida = [];
const memoria = $getWorkflowStaticData('global');
memoria.vigilancia = memoria.vigilancia || {};
for (const item of $input.all()) {
  const cfg = item.json;
  const a = await auditar(cfg);
  const dominio = a.origen.replace(/^https?:\/\//, '');
  const revisadas = a.paginas.length || 1;

  const problemas = Object.values(a.problemasPorId).map(p => {
    const [nivel, titulo, porque, solucion] = CATALOGO[p.id];
    return { id: p.id, nivel, titulo, porque, solucion, afectadas: p.paginas.length, ejemplos: p.paginas.slice(0, 3).map((u, i) => u.replace(a.origen, '') + (p.detalles[i] ? ` (${p.detalles[i]})` : '')) };
  }).sort((x, y) => ORDEN[x.nivel] - ORDEN[y.nivel] || y.afectadas - x.afectadas);

  // Nota: cada tipo de problema resta según su gravedad y el % de páginas afectadas
  let nota = 100;
  for (const p of problemas) nota -= PESO[p.nivel] * (p.afectadas ? Math.min(1, 0.3 + 0.7 * p.afectadas / revisadas) : 1);
  nota = a.problemasPorId.web_inaccesible ? 0 : Math.max(0, Math.round(nota));
  const cuenta = n => problemas.filter(p => p.nivel === n).length;

  const porUrl = {};
  Object.values(a.problemasPorId).forEach(p => p.paginas.forEach(u => (porUrl[u] = porUrl[u] || []).push(p.id)));
  const paginas = a.paginas.map(p => ({
    url: p.url, status: p.status || 0,
    problemas: (porUrl[p.url] || []).sort((x, y) => ORDEN[CATALOGO[x][0]] - ORDEN[CATALOGO[y][0]]).map(id => ({ nivel: CATALOGO[id][0], titulo: CATALOGO[id][1] })),
    title: p.title || ''
  })).sort((x, y) => (y.problemas.filter(q => q.nivel !== 'recomendacion').length - x.problemas.filter(q => q.nivel !== 'recomendacion').length) || (y.problemas.length - x.problemas.length));

  // Vigilancia: qué ha cambiado desde la semana anterior
  const vigilando = cfg.modo === 'vigilancia';
  const anterior = vigilando ? memoria.vigilancia[dominio] : undefined;
  const actuales = Object.fromEntries(problemas.map(p => [p.id, p.afectadas]));
  const nuevos = anterior ? problemas.filter(p => !(p.id in anterior.problemas) || (p.nivel === 'critico' && p.afectadas > anterior.problemas[p.id])) : [];
  const resueltos = anterior ? Object.keys(anterior.problemas).filter(id => !(id in actuales)).map(id => CATALOGO[id][1]) : [];
  if (vigilando) memoria.vigilancia[dominio] = { fecha: new Date().toISOString().slice(0, 10), nota, problemas: actuales };

  const icono = { critico: '🔴', importante: '🟠', recomendacion: '🔵' };
  let mensaje = '';
  if (vigilando) {
    if (!anterior) mensaje = `*Vigilancia SEO · ${dominio}*\nPrimera revisión: nota *${nota}/100* · ${cuenta('critico')} críticos, ${cuenta('importante')} importantes, ${cuenta('recomendacion')} recomendaciones. A partir de ahora solo aviso de cambios.`;
    else if (nuevos.length || nota <= anterior.nota - 5) mensaje = `*Vigilancia SEO · ${dominio}*\nNota *${nota}/100* (semana anterior: ${anterior.nota})\n\n*Nuevo:*\n${nuevos.map(p => `${icono[p.nivel]} ${p.titulo} — ${p.afectadas || 'todo el sitio'}${p.afectadas ? ' páginas' : ''}\n      ej.: ${p.ejemplos[0] || dominio}`).join('\n') || '—'}${resueltos.length ? `\n\n*Resuelto:* ${resueltos.join(', ')}` : ''}`;
  }

  salida.push({ json: {
    modo: cfg.modo, formato: cfg.formato, canal: cfg.canal || '', web: cfg.web, dominio, origen: a.origen,
    fecha: new Date().toISOString().slice(0, 10), segundos: Math.round((Date.now() - a.inicio) / 1000),
    nota, nivel: nota >= 85 ? 'Bien' : nota >= 65 ? 'Mejorable' : 'Necesita trabajo',
    criticos: cuenta('critico'), importantes: cuenta('importante'), recomendaciones: cuenta('recomendacion'),
    revisadas: a.paginas.length, urlsEnSitemap: a.total, sitemap: a.sitemapUrl || null,
    sitio: a.sitio, problemas, paginas, notas: a.notas,
    hayAlertas: Boolean(mensaje), mensajeSlack: mensaje
  } });
}
return salida;

// Devuelve el informe en JSON o en HTML según ?formato=
const r = $input.first().json;
if (r.formato !== 'html') return [{ json: { body: JSON.stringify(r, null, 2), contentType: 'application/json; charset=utf-8' } }];

const e = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const NIVEL = { critico: ['Crítico', 'c'], importante: ['Importante', 'i'], recomendacion: ['Recomendación', 'r'] };
const colorNota = r.nota >= 85 ? 'bien' : r.nota >= 65 ? 'med' : 'mal';
const si = ok => ok ? '<span class="ok">Sí</span>' : '<span class="ko">No</span>';

const prioridades = r.problemas.map((p, i) => `<tr>
