<td><b>${e(p.titulo)}</b><div class="g">${p.ejemplos.map(e).join('<br>')}</div></td>
<td class="n">${p.afectadas || 'sitio'}</td><td>${e(p.porque)}</td><td>${e(p.solucion)}</td></tr>`).join('')
  || '<tr><td colspan="6" class="g">No se ha encontrado ningún problema.</td></tr>';

const urls = r.paginas.map((p, i) => `<tr><td class="n g">${i + 1}</td>
<td><a href="${e(p.url)}" target="_blank">${e(p.url.replace(r.origen, '') || '/')}</a><div class="g">${e(p.title)}</div></td>
<td class="n">${p.status || '—'}</td>
