<div class="res"><div><b class="${colorNota}">${r.nota}</b><span>de 100 · ${e(r.nivel)}</span></div>
<div><b class="mal">${r.criticos}</b><span>críticos</span></div><div><b class="med">${r.importantes}</b><span>importantes</span></div><div><b style="color:#0550ae">${r.recomendaciones}</b><span>recomendaciones</span></div></div>
